diff --git a/agent/src/club/streak.js b/agent/src/club/streak.js
new file mode 100644
index 0000000..5db66ac
--- /dev/null
+++ b/agent/src/club/streak.js
@@ -0,0 +1,53 @@
+export function streak(history, now = new Date()) {
+  if (!Array.isArray(history) || history.length === 0) return 0;
+  const nowDate = new Date(now);
+  const nowTime = nowDate.getTime();
+  const dates = [];
+  for (const h of history) {
+    if (!h || typeof h.date !== 'string') continue;
+    const d = new Date(h.date + 'T00:00:00');
+    if (isNaN(d)) continue;
+    if (d.getTime() > nowTime) continue;
+    dates.push(d);
+  }
+  if (dates.length === 0) return 0;
+
+  const getWeekStart = (date) => {
+    const d = new Date(date);
+    const day = d.getDay();
+    const diff = (day === 0 ? -6 : 1 - day);
+    const monday = new Date(d);
+    monday.setDate(d.getDate() + diff);
+    monday.setHours(0,0,0,0);
+    return monday.getTime();
+  };
+
+  const weekStartNow = getWeekStart(nowDate);
+  const weekStartPrev = weekStartNow - 7 * 24 * 60 * 60 * 1000;
+
+  const weekHasGame = (weekStart) => {
+    const weekEnd = weekStart + 7 * 24 * 60 * 60 * 1000 - 1;
+    return dates.some(d => {
+      const t = d.getTime();
+      return t >= weekStart && t < weekStart + 7 * 24 * 60 * 60 * 1000;
+    });
+  };
+
+  let currentWeekStart = weekStartNow;
+  if (!weekHasGame(currentWeekStart)) {
+    currentWeekStart = weekStartPrev;
+    if (!weekHasGame(currentWeekStart)) return 0;
+  }
+
+  let count = 0;
+  let ws = currentWeekStart;
+  while (true) {
+    if (weekHasGame(ws)) {
+      count++;
+      ws -= 7 * 24 * 60 * 60 * 1000;
+    } else {
+      break;
+    }
+  }
+  return count;
+}

